export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "エレベーターは狭かった。定員九名と表示されているが、九人も乗ったらきっと抱き合うしかない。奥の壁の鏡には引っかき傷が何本も走り、検査合格証の日付は三年前だった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）鏡は見ない。ルールにはないけど、自分で足した。", background: Background.Root_Act2_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四を押す。ボタンがオレンジ色の輪に光り、エレベーターがガクンと一度揺れて、上へのぼり始めた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四階の廊下は明かりが消えていて、突き当たりの非常口の表示だけが、緑色にぼうっと浮かんでいた。ある部屋の前に男物のスリッパが一足、つま先を扉のほうへ向けて、きちんと揃えて置いてある。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアが閉まる。二。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二階では、どこかの家のテレビがまだついていて、鉄の扉越しに効果音の笑い声が聞こえてきた。波のように、笑っては静まり、静まってはまた笑う。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）夜中の二時にバラエティ番組。わたしより健康的。", background: Background.Root_Act2_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "六。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "六階には線香の匂いがした。かすかに、湿った壁の匂いと混じって。ドアが開いていた数秒のあいだ、廊下の奥でスリッパが床を叩く音がした。ペタ、ペタ、ペタ、とこちらへ近づいてきて——そこでドアが閉まった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "そっち、すごく静かだね。", background: Background.Root_Act2_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "六階で誰か線香焚いてる。", background: Background.Root_Act2_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "……ちょっと、怖がらせないでよ。", background: Background.Root_Act2_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "行けって言ったの、そっちでしょ。", background: Background.Root_Act2_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "テレビはまだついていた。効果音の笑い声が湧き上がる——同じところだ。同じ高さ、最後に声が裏返る同じ女。誰かがその十秒を巻き戻して、もう一度再生したかのように。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）バラエティは再放送するもの。ごく普通。", background: Background.Root_Act2_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "十を押す。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "上へのぼる時間は、覚えていたよりも長かった。赤い数字は一つ変わるたびに、少しずつ長くためらうようになっていく。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "八で、頭上の蛍光灯が一度ちらついた。九で、さらに二度。暗くなり、また無理やり明るさを取り戻す。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "念念？　今どこ？", background: Background.Root_Act2_S1, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "方芮の声は半拍遅れて届いた。深い水の底から浮かび上がってくるように。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "十。", background: Background.Root_Act2_S1, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "十階でドアが開いた。外は暗かった。廊下がどこまで続いているのかもわからないほどに。ただ冷たい空気がゆっくりと流れ込んできて、足首にまとわりついた。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "五を押す。ドアが閉まったその瞬間になって、ずっと息を止めていたことにようやく気づいた。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "……じゅう……いま……十って？", background: Background.Root_Act2_S1, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一語一語のあいだに、ザザッというノイズが挟まる。湿気を吸ったカセットテープのように。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "九。八。七。六。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "五。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "チン。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "まず、冷気。雨上がりのような冷たさ。湿っていて、アスファルトと錆の匂いがする。それから靴。黒いフラットシューズが、ぐっしょりと濡れたまま、音もなくエレベーターに踏み込んできた。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）顔を上げちゃだめ。", background: Background.Root_Act2_S1, portrait: Portrait.XuNian_Scared },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "エレベーターがわずかに沈んだ。人ひとり分の重さが加わったように。ほんの少しだけ。人ひとりよりも、軽く。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は自分のスニーカーを見つめた。左の靴紐がほどけているが、しゃがんで結び直す勇気はない。視界の端で、あのフラットシューズが隅に止まっている。つま先を、こちらに向けて。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "長い髪がひと房垂れ下がり、その毛先から水が滴っていた。一滴、床に落ちる。また一滴。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "念念？　誰か乗ってきた？　ねえ、なんか言ってよ。", background: Background.Root_Act2_S1, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）あの人に話しかけちゃだめ。じゃあ、電話の相手は？　書いてない。", background: Background.Root_Act2_S1, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "唇を噛む。人差し指がボタンの上で一秒止まり、それから一を押した。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアが閉まる。エレベーターが動き出す。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "上へ。", background: Background.Root_Act2_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "六。七。八。九。", background: Background.Root_Act2_S1 },
];
